// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(address depositor, uint256 amount) public {
        vm.assume(depositor != address(0));
        uint256 amt = bound(amount, 1 wei, 1 ether);

        vm.deal(depositor, amt);
        vm.prank(depositor);
        c.deposit{value: amt}();

        uint256 before = address(c).balance;
        vm.prank(depositor);
        c.withdrawAll();

        assertTrue(address(c).balance == before - amt);
    }
}
